/* Frappe's print stylesheet sets `.print-format td, .print-format th { padding:
   10px !important }`, which no amount of specificity beats — it is what stacked
   the identity block onto two lines per row and double-spaced the module list.
   Every table rule here is scoped under .print-format and marked !important for
   that reason, not out of habit.

   The institute green is written out literally in both places it appears rather
   than as a custom property: this site renders PDFs with wkhtmltopdf, whose
   WebKit predates CSS variables, so a var() would look correct in the browser
   preview and come out black in the PDF anyone receives. Adjust both if it reads
   off against the letterhead. */

/* The letterhead image carries the logo on its left and the institute text to
   the right of it. Centred as a block, the text lands right of the page centre —
   measured on a rendered page, the logo sat at x 60-220 and the text at 260-752,
   putting the text's centre at 506 against a page centre of 413.

   Shifting the whole image left by that 93px would take the logo off the page,
   so it is anchored to the left margin and scaled instead: at 78% the text
   centres on the page and the logo stays inside it. The header prints smaller
   than the original as a result — recomposing the image so its text is centred
   over the full width would avoid that, and is the better fix if it matters. */
.print-format .proof-letterhead {
	margin-bottom: 10px;
	text-align: left !important;
}
.print-format .proof-letterhead div {
	text-align: left !important;
}
.print-format .proof-letterhead img {
	width: 78%;
	max-width: 78%;
	height: auto;
}

.print-format .proof-of-registration {
	font-size: 11pt;
	line-height: 1.4;
	color: #000;
}

.print-format .proof-title {
	text-align: center;
	font-size: 15pt;
	font-weight: bold;
	color: #1a7a3c;
	margin: 0 0 20px;
}

.print-format .proof-date {
	text-align: right;
	margin: 0 0 20px;
}

/* Fixed label and colon columns so the colons line up, rather than each row
   ending wherever its label happens to. */
.print-format .proof-identity {
	border: none;
	border-collapse: collapse;
	width: auto;
	margin: 0 0 26px;
	font-weight: bold;
}
.print-format .proof-identity td {
	border: none !important;
	padding: 0 0 2px 0 !important;
	vertical-align: baseline !important;
	white-space: nowrap;
}
.print-format .proof-identity td.label {
	width: 120px;
}
.print-format .proof-identity td.colon {
	width: 16px;
}

.print-format .proof-lead {
	margin: 0 0 18px;
}

.print-format .proof-qualification {
	margin: 0 0 20px;
}

.print-format .proof-modules {
	width: 100%;
	border-collapse: collapse;
	margin: 0 0 22px;
}
.print-format .proof-modules th,
.print-format .proof-modules td {
	border: none !important;
	text-align: left;
	padding: 0 0 3px 0 !important;
	vertical-align: baseline !important;
	font-weight: normal;
}
.print-format .proof-modules th {
	padding-bottom: 12px !important;
	font-weight: bold;
}
/* Fixed rather than proportional, so the names line up in a column the way the
   typed original does. */
.print-format .proof-modules .module-code {
	width: 255px;
}

.print-format .proof-period {
	margin: 0 0 16px;
}

.print-format .proof-acknowledgement {
	margin: 0 0 8px;
}

/* The mark sits directly on the rule, so the signature reads as signed rather
   than as an image placed near a line. */
.print-format .proof-signature {
	margin-top: 38px;
	page-break-inside: avoid;
}
.print-format .proof-signature .signature-image {
	display: block;
	height: 46px;
	width: auto;
	max-width: 240px;
	margin-bottom: -6px;
}
.print-format .proof-signature .signature-space {
	height: 40px;
}
.print-format .proof-signature .signature-rule {
	border-top: 1px solid #000;
	width: 220px;
}
.print-format .proof-signature .signature-label {
	font-weight: bold;
	color: #1a7a3c;
	padding-top: 2px;
	line-height: 1.3;
}
